  const left = Math.round(insets.left), top = Math.round(insets.top);
  const right = Math.round(insets.right), bottom = Math.round(insets.bottom);
  const viewWidth = Math.max(1, Math.round(width) - left - right);
  const viewHeight = Math.max(1, Math.round(height) - top - bottom);
