window.addEventListener("pointermove", moveSidebarResize, {passive:false});
window.addEventListener("pointerup", finishSidebarResize);
window.addEventListener("pointercancel", finishSidebarResize);

try {
  const saved = Number(localStorage.getItem(SIDEBAR_WIDTH_STORAGE_KEY));
  if (Number.isFinite(saved) && saved > 0) setSidebarWidth(saved);
} catch (_) {}
const sidebarGeometryObserver = typeof ResizeObserver === "function"
  ? new ResizeObserver(() => scheduleSidebarGeometry()) : null;
sidebarGeometryObserver?.observe(sidebarDeck);
window.addEventListener("resize", () => {
  if (sidebarWidth !== null) setSidebarWidth(sidebarWidth);
  else scheduleSidebarGeometry();
});
requestAnimationFrame(scheduleSidebarGeometry);

// ── The turn plate's own width ─────────────────────────────────────────────
//
