// seam on its right edge is the command deck's affordance brought inside the
// masthead: drag it and the plate keeps the width, the standings re-divide
// what remains. Width is a small local preference like the deck's. Without
// one, a roomy masthead spends some of its spare width on the two-column plate;
// narrower boxes keep the compact authored track. Past TURN_PLATE_SPLIT_WIDTH
// the plate has more width than one settings column can spend, so it goes wide
// instead of tall: the era and the turn counter share the first line and the
// settings below divide into two columns.
//
// The seam is re-rendered with the masthead's markup every frame, so nothing
// binds to the element itself: the press is caught on #playerhud, which is
// permanent, and the drag lives on window like every layout gesture here.
const TURN_PLATE_WIDTH_STORAGE_KEY = "civvis-turn-plate-width-v1";
const TURN_PLATE_MIN_WIDTH = 148;
const TURN_PLATE_SPLIT_WIDTH = 252;
const TURN_PLATE_AUTO_WIDE_HUD_WIDTH = 1500;
const TURN_PLATE_AUTO_WIDE_MAX_WIDTH = 304;
let turnPlateWidth = (() => {
  const saved = Number(localStorage.getItem(TURN_PLATE_WIDTH_STORAGE_KEY));
  return Number.isFinite(saved) && saved >= TURN_PLATE_MIN_WIDTH
    ? Math.round(saved) : null;
})();
let turnPlateSeamGesture = null;

// The standings keep a readable stretch beside the plate. They scroll
// sideways inside their own frame, so the table survives any division — this
// floor only keeps the plate from swallowing the whole masthead.
function turnPlateMaxWidth() {
  const hud = document.getElementById("playerhud");
  return Math.max(TURN_PLATE_MIN_WIDTH, (hud?.clientWidth || 0) - 240);
}

// The automatic track follows the overlay's own live width rather than the
// browser. That covers ultrawide displays, a hidden victory rail, and a
// manually resized standings window with the same rule. The lower bound stays
// comfortably beyond the split threshold; from there the plate grows gently
// until each settings column has all the room it can use.
function automaticTurnPlateWidth() {
  const hud = document.getElementById("playerhud");
  if (!hud || hud.clientWidth < TURN_PLATE_AUTO_WIDE_HUD_WIDTH) return null;
  return Math.round(Math.min(TURN_PLATE_AUTO_WIDE_MAX_WIDTH,
    Math.max(TURN_PLATE_SPLIT_WIDTH + 12, hud.clientWidth * .18)));
}

// Re-resolve a preferred or automatic width against the room available now.
// Crucially this does not overwrite turnPlateWidth: a wide preference clamped
// by a temporary split-screen window returns when that room returns.
function syncTurnPlateWidth() {
  const hud = document.getElementById("playerhud");
  if (!hud) return;
  const desired = turnPlateWidth ?? automaticTurnPlateWidth();
  const effective = Number.isFinite(desired)
    ? Math.round(Math.max(TURN_PLATE_MIN_WIDTH, Math.min(turnPlateMaxWidth(), desired)))
    : null;
  if (effective === null) hud.style.removeProperty("--turn-plate-width");
  else hud.style.setProperty("--turn-plate-width", `${effective}px`);
  hud.classList.toggle("turn-plate-wide",
    effective !== null && effective >= TURN_PLATE_SPLIT_WIDTH);
  const seam = hud.querySelector("[data-turn-plate-seam]");
  if (seam) {
    seam.setAttribute("aria-valuemin", `${TURN_PLATE_MIN_WIDTH}`);
    seam.setAttribute("aria-valuemax", `${Math.round(turnPlateMaxWidth())}`);
    seam.setAttribute("aria-valuenow",
      `${effective ?? Math.round(hud.querySelector(".victory-turn")?.getBoundingClientRect().width || TURN_PLATE_MIN_WIDTH)}`);
  }
}

function applyTurnPlateWidth(width, persist = true) {
  // `Number(null)` is 0, and a clamped 0 is the minimum width — so a reset
  // has to be told apart from a narrow drag before any arithmetic happens.
  const candidate = width === null || width === undefined ? NaN : Number(width);
  turnPlateWidth = Number.isFinite(candidate)
    ? Math.round(Math.max(TURN_PLATE_MIN_WIDTH, Math.min(turnPlateMaxWidth(), candidate)))
    : null;
  syncTurnPlateWidth();
  if (persist) {
    try {
      if (turnPlateWidth === null) localStorage.removeItem(TURN_PLATE_WIDTH_STORAGE_KEY);
      else localStorage.setItem(TURN_PLATE_WIDTH_STORAGE_KEY, `${turnPlateWidth}`);
    } catch (_) {}
  }
}

function beginTurnPlateSeamGesture(event) {
  if (event.button !== undefined && event.button !== 0) return;
  const plate = document.getElementById("playerhud")?.querySelector(".victory-turn");
  if (!plate) return;
  event.preventDefault();
  event.stopPropagation();
  turnPlateSeamGesture = {
    pointerId:event.pointerId, startX:event.clientX,
    startWidth:plate.getBoundingClientRect().width, moved:false,
  };
  document.body.classList.add("layout-resizing");
  document.body.style.setProperty("--layout-resize-cursor", "col-resize");
}

function moveTurnPlateSeamGesture(event) {
  const gesture = turnPlateSeamGesture;
  if (!gesture || event.pointerId !== gesture.pointerId) return;
  event.preventDefault();
  const dx = event.clientX - gesture.startX;
  if (Math.abs(dx) > 1) gesture.moved = true;
  if (gesture.moved) applyTurnPlateWidth(gesture.startWidth + dx, false);
}

function finishTurnPlateSeamGesture(event) {
  const gesture = turnPlateSeamGesture;
  if (!gesture || (event && event.pointerId !== gesture.pointerId)) return;
  turnPlateSeamGesture = null;
  document.body.classList.remove("layout-resizing");
  document.body.style.removeProperty("--layout-resize-cursor");
  if (gesture.moved) applyTurnPlateWidth(turnPlateWidth);
}

{
  const hud = document.getElementById("playerhud");
  hud?.addEventListener("pointerdown", event => {
    if (event.target.closest?.("[data-turn-plate-seam]"))
      beginTurnPlateSeamGesture(event);
  });
  hud?.addEventListener("dblclick", event => {
    if (!event.target.closest?.("[data-turn-plate-seam]")) return;
    event.preventDefault();
    applyTurnPlateWidth(null);
  });
  hud?.addEventListener("keydown", event => {
    const seam = event.target.closest?.("[data-turn-plate-seam]");
    if (!seam) return;
    const step = event.shiftKey ? 24 : 8;
    const current = turnPlateWidth
      ?? hud.querySelector(".victory-turn")?.getBoundingClientRect().width
      ?? TURN_PLATE_MIN_WIDTH;
    let next = null;
    if (event.key === "ArrowLeft") next = current - step;
    if (event.key === "ArrowRight") next = current + step;
    if (event.key === "Home") next = TURN_PLATE_MIN_WIDTH;
    if (event.key === "End") next = turnPlateMaxWidth();
    if (next === null) return;
    event.preventDefault();
    event.stopPropagation();
    applyTurnPlateWidth(next);
  });
  window.addEventListener("pointermove", moveTurnPlateSeamGesture, {passive:false});
  window.addEventListener("pointerup", finishTurnPlateSeamGesture);
  window.addEventListener("pointercancel", finishTurnPlateSeamGesture);
  // Player HUD width can change without a window resize: hiding the victory
  // rail or dragging any of this overlay's edges must refit the automatic
  // plate immediately. Its inner track cannot resize the observed outer box,
  // so this observer has no feedback loop.
  const turnPlateSizeObserver = typeof ResizeObserver === "function"
    ? new ResizeObserver(syncTurnPlateWidth) : null;
  turnPlateSizeObserver?.observe(hud);
  syncTurnPlateWidth();
}

// ------------------------------------------------------------- HUD folds
// Each half of the two composite panels collapses on its own: the masthead's
// turn box and player standings, and the right rail's simulation stats and
// victory tracker. A fold keeps the widget where it is — unlike the Display
// Settings switches, which take a whole widget off the map — so the other
// half simply receives the room. The two masthead halves are exclusive:
// collapsing the only visible half swaps the fold rather than emptying the
// panel.
const HUD_FOLD_STORAGE_KEY = "civvis-hud-folds-v1";
const HUD_FOLD_NAMES = ["simstats", "victory", "turnplate", "standings"];
let HUD_FOLDS = (() => {
  const folds = {};
  try {
    const saved = JSON.parse(localStorage.getItem(HUD_FOLD_STORAGE_KEY) || "{}");
    for (const name of HUD_FOLD_NAMES) {
      if (typeof saved?.[name] === "boolean") folds[name] = saved[name];
    }
  } catch (_) {}
  return folds;
})();
function hudFolded(name) { return HUD_FOLDS[name] === true; }
function saveHudFolds() {
  try { localStorage.setItem(HUD_FOLD_STORAGE_KEY, JSON.stringify(HUD_FOLDS)); } catch (_) {}
}
function applyHudFolds() {
  const playerHud = document.getElementById("playerhud");
  playerHud?.classList.toggle("turn-plate-collapsed", hudFolded("turnplate"));
  playerHud?.classList.toggle("standings-collapsed", hudFolded("standings"));
  const victoryHud = document.getElementById("victoryhud");
  victoryHud?.classList.toggle("sim-stats-collapsed", hudFolded("simstats"));
  victoryHud?.classList.toggle("victory-collapsed", hudFolded("victory"));
}
function toggleHudFold(name) {
  if (!HUD_FOLD_NAMES.includes(name)) return;
  const folded = !hudFolded(name);
  if (folded && name === "turnplate" && hudFolded("standings")) HUD_FOLDS.standings = false;
  if (folded && name === "standings" && hudFolded("turnplate")) HUD_FOLDS.turnplate = false;
  HUD_FOLDS[name] = folded;
  saveHudFolds();
  applyHudFolds();
  if (state) drawPlayerHud();
  syncTurnPlateWidth();
  syncSimStatsHeight();
  refitMapAreaToChrome();
}
function hudFoldButton(name, label, extraClass = "") {
  const folded = hudFolded(name);
  const verb = folded ? "Expand" : "Collapse";
  return `<button class="hud-fold${extraClass ? ` ${extraClass}` : ""}" type="button" data-hud-fold="${name}" ` +
    `aria-expanded="${!folded}" aria-label="${verb} the ${label}" title="${verb} the ${label}">${folded ? "▸" : "▾"}</button>`;
}

// ------------------------------------------------------- simulation stats
// The record that persists between simulations: every finished game bumps a
// win–loss–draw ledger per civilization and per controlling player or AI
// profile, plus a count of wins by victory type. It stays per mode so a
// Tactics record never mixes into a Civ one.
// Aggregates only — the ledger stays a few hundred bytes however many games
// it has seen.
const SIMULATION_STATS_KEY = "civvis-simulation-stats-v1";
const SIM_STATS_VIEW_KEY = "civvis-sim-stats-view-v1";
const SIM_STATS_VIEWS = {
  civs: {label: "Civs", title: "Win–loss record by civilization"},
  strategies: {label: "Strategies", title: "Win–loss record by controlling player or AI profile"},
  victories: {label: "Victory types", title: "Wins by victory type"},
};
let simulationStats = (() => {
  try {
    const saved = JSON.parse(localStorage.getItem(SIMULATION_STATS_KEY) || "{}");
    if (saved && typeof saved === "object" && !Array.isArray(saved)) return saved;
  } catch (_) {}
  return {};
})();
let simStatsView = (() => {
  try {
    const saved = localStorage.getItem(SIM_STATS_VIEW_KEY);
    return SIM_STATS_VIEWS[saved] ? saved : "civs";
  } catch (_) { return "civs"; }
})();
function saveSimulationStats() {
  try { localStorage.setItem(SIMULATION_STATS_KEY, JSON.stringify(simulationStats)); } catch (_) {}
}
function rememberSimStatsView(view) {
  simStatsView = SIM_STATS_VIEWS[view] ? view : "civs";
  try { localStorage.setItem(SIM_STATS_VIEW_KEY, simStatsView); } catch (_) {}
}
function simulationStatsMode(st = state) {
  return st && isBattlefieldMapScript(st.map?.script) ? "tactics" : "civ";
}
function simulationStatsBucket(mode) {
  const bucket = simulationStats[mode] ?? (simulationStats[mode] = {});
  bucket.games ??= 0;
  bucket.turns ??= 0;
  bucket.civs ??= {};
  bucket.strategies ??= {};
  bucket.victories ??= {};
  return bucket;
}
// The seat's controller, the same preference order the standings print:
// a registered person, then the league handle, then the plain AI name.
function simulationSeatName(p) {
  return p.player_username || p.ai_username || p.ai_name || "AI player";
}
function bumpSimulationRecord(table, key, column) {
  const row = table[key] ?? (table[key] = {w:0, l:0, d:0});
  row[column] += 1;
}
function bumpSimulationVictory(table, victory) {
  table[victory] = (Number(table[victory]) || 0) + 1;
}
// Called from the result screens, whose signature guard already runs once per
// distinct result; the stored key repeats that guard across reloads so a page
// reopened over a finished world cannot count the same game twice.
function recordSimulationResult(st, signature, winnerIds) {
  const key = `${st.server_instance ?? ""}|${signature}`;
  if (simulationStats.last === key) return;
  simulationStats.last = key;
  const bucket = simulationStatsBucket(simulationStatsMode(st));
  bucket.games += 1;
  bucket.turns += Number(reportedTurn(st)) || 0;
  const winnerSeats = new Set(winnerIds
    .map(id => st.players[id]?.id)
    .filter(id => id !== undefined));
  if (winnerSeats.size)
    bumpSimulationVictory(bucket.victories, victoryVerdict(st.victory_type, st.victory_label));
  for (const p of st.players) {
    if (p.is_minor || p.is_barbarian) continue;
    const column = winnerSeats.size === 0 ? "d" : winnerSeats.has(p.id) ? "w" : "l";
    bumpSimulationRecord(bucket.civs, p.civ || "Unknown civilization", column);
    bumpSimulationRecord(bucket.strategies, simulationSeatName(p), column);
  }
  saveSimulationStats();
  if (state) drawPlayerHud();
}
function clearSimulationStats(mode) {
  delete simulationStats[mode];
  saveSimulationStats();
  if (state) drawPlayerHud();
}

// -------------------------------------------------- simulation stats seam
// The divider between the simulation stats and the victory tracker: the turn
// plate's seam turned on its side. Without a preference the top section takes
// its content height (capped by the stylesheet) and the tracker keeps the
