  const width = CIV6_FLAG_PLATE_ATLAS.naturalWidth;
  if (!cell || width !== cell * CIV6_FLAG_PLATE_STYLES.length) return;
  const sheet = document.createElement("canvas");
  sheet.width = width; sheet.height = cell;
