  takeCameraControl();
  const to = {x:pan.x, y:pan.y};
  const want = Math.max(planetMinScale(), scale);
  const path = skyTravelPath({...SKY_PAN}, skyStageWidth(cam.scale),
                             to, skyStageWidth(want));
