// is not a second opinion about how far out anything is — it is the gearing's
// own ruler with a handle on it.
function skyLadderAt(scale = cam.scale) {
  const floor = Math.max(1e-30, planetMinScale());
  const ladder = skyZoomLadder();
  if (!(ladder > 0)) return 1;
  return Math.max(0, Math.min(1, Math.log(Math.max(floor, scale) / floor) / ladder));
}
