  if (!(radii > 0)) return "—";
  if (radii >= LIGHT_YEAR * .04) return `${skyRoundSpan(radii / LIGHT_YEAR)} ly`;
  if (radii >= AU * .015) return `${skyRoundSpan(radii / AU)} AU`;
  const km = radii * EARTH_KM;
  if (km >= 1e6) return `${skyRoundSpan(km / 1e6)}M km`;
  return `${Math.round(km).toLocaleString("en")} km`;
