  cx.fillRect(x - width / 2 - scale, barY - scale, width + 2 * scale, height + 2 * scale);
  cx.fillStyle = "#8e3f3d"; cx.fillRect(x - width / 2, barY, width, height);
  cx.fillStyle = status.fill;
  cx.fillRect(x - width / 2, barY, width * status.loyalty / 100, height);
  cx.globalAlpha = 1; cx.textAlign = "center"; cx.textBaseline = "top";
  cx.font = `850 ${8.2 * scale}px Inter,sans-serif`;
  cx.lineWidth = 2.6 * scale; cx.strokeStyle = "#07100e"; cx.fillStyle = "#fff5d9";
  const rate = Math.round(status.rate);
  const label = `${Math.round(status.loyalty)} ${rate >= 0 ? "+" : ""}${rate}`;
  cx.strokeText(label, x, barY + height + 2.1 * scale);
