  cx.textAlign = "center"; cx.textBaseline = "top";
  cx.font = `850 ${8.2 * scale}px Inter,sans-serif`;
  cx.lineWidth = 2.6 * scale; cx.strokeStyle = "#07100e"; cx.fillStyle = "#fff5d9";
  const label = `${lensPowerAmount(status.supply)}/${lensPowerAmount(status.demand)} ⚡`;
