  const territory = state.map.tiles.filter(tile => tile.owner === player);
  const units = state.units.filter(unit => unit.owner === player);
  const owned = territory.map(tile => tile.pos);
  const wars = (state.wars || []).filter(war =>
    (war.ended === null || war.ended === undefined) &&
    (war.aggressor === player || war.defender === player));
  const enemies = new Set(wars.map(war =>
    war.aggressor === player ? war.defender : war.aggressor));
