  const maximum = oneEmpire ? 1.12 : .82;
  if (planetMap()) return observedPlanetViewGoal(anchors, maximum);
  const points = unwrapObservedPoints(anchors);
  const projected = points.map(point => ({
    x:COSR * point.x - SINR * point.y,
    y:SINR * point.x + COSR * point.y,
  }));
