    if (!next || !Array.isArray(next.step)) { unitOrders.delete(unitId); return false; }
    const before = unit.pos;
    render(await fetchJSON("/action", {
      method: "POST",
      headers: {"Content-Type": "application/json"},
      body: JSON.stringify({action: {type: "move_to", unit: unitId, to: next.step}}),
    }));
    const after = state.units.find(candidate => candidate.id === unitId);
