// Hand your own seat to one of our strategies for a stretch of turns. Useful
// for skipping a decided game, and for seeing how a rated agent would play the
// position you are in — which is most of why Unciv has it. Which agent and how
// many turns are both choices, so both are selects rather than modifier keys.
let autoplaying = false, autoplayStop = false;
const AUTOPLAY_STRATEGY_KEY = "civvis-autoplay-strategy-v1";
const AUTOPLAY_BATCH_TIMEOUT_MS = 120000;
let autoplayRequestSequence = 0;
// Fill the agent picker from the roster the server offers. Every entrant is
// one of ours, named by its handle, so the choice is between agents and not
// between adjectives. The seat's current agent is preselected, so pressing
// Auto-play without touching this changes nothing about who plays.
function fillStrategies(rules) {
  const select = document.getElementById("autoplaystrategy");
  const roster = Array.isArray(rules.strategies) ? rules.strategies : [];
  if (!select || !roster.length) return;
  select.innerHTML = roster.map(entry =>
    `<option value="${escapeAttr(entry.name)}" title="${escapeAttr(entry.label || entry.name)}">` +
      `${escapeAttr(entry.username || entry.name)}</option>`).join("");
  let remembered = null;
  try { remembered = localStorage.getItem(AUTOPLAY_STRATEGY_KEY); } catch (e) {}
  const wanted = [remembered, rules.seat_strategy]
    .find(name => name && roster.some(entry => entry.name === name));
  select.value = wanted || roster[0].name;
  syncAutoplayLabel();
}
// "All" is the turns this game has left. A continued game deliberately has no
// cap, so use a stop-button-sized horizon: a next-victory run will finish when
// the engine declares it, and an indefinite run continues until stopped.
function autoplayRequest() {
  const pick = (document.getElementById("autoplayturns") || {}).value || "1";
  if (pick === "all" && (state || {}).turn_limit === null) return 1000000000;
  const cap = +(state || {}).turn_limit || +(state || {}).max_turns || 0;
  const left = Math.max(1, cap - (+(state || {}).turn || 0) + 1);
  return pick === "all" ? left : Math.min(+pick, left);
}
// The button says how long the seat goes on loan for — "Auto-play 10 turns"
// — so what pressing it does is read off the button, not off the picker
// beside it. "All" is the turns this game has left; a game with no cap runs
// until stopped. A run in progress owns the button and says so itself.
function syncAutoplayLabel() {
  const button = document.getElementById("autoplaybtn");
  if (!button || autoplaying) return;
  const pick = (document.getElementById("autoplayturns") || {}).value || "1";
  const unbounded = pick === "all" && !!state && (state.turn_limit ?? state.max_turns) === null;
  const turns = state ? autoplayRequest() : (pick === "all" ? null : +pick);
  button.textContent = unbounded ? "▶▶ Auto-play until stopped"
    : turns ? `▶▶ Auto-play ${turns} turn${turns === 1 ? "" : "s"}`
    : "▶▶ Auto-play all turns";
}
function setAutoplayNote(text) {
  const note = document.getElementById("autoplaynote");
  if (note) note.textContent = text || "";
}
function retryableAutoplayFetch(error) {
  return error && (error.name === "AbortError" || error instanceof TypeError);
}
// A turn batch mutates the world before its large state response reaches the
// page. If that socket is dropped, blindly posting it again would play the
// same turns twice. Give the batch a page-unique id and retry that id once:
// the server remembers the completed result and turns the retry into an
// acknowledgement. The generous timeout is deliberate too — the generic
// request budget is 15 seconds, but a late-game batch can exceed that on a
// machine compiling several CIVVIS branches without being stuck.
async function autoplayBatch(turns, strategy) {
  const requestId = `${VIEWER_ID}-autoplay-${++autoplayRequestSequence}`;
  const body = JSON.stringify({
    turns, strategy, request_id: requestId,
    seed: (state || {}).seed,
    server_instance: (state || {}).server_instance,
  });
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const next = await fetchJSON("/autoplay", {
        method: "POST",
        headers: {"Content-Type": "application/json"},
        body,
      }, AUTOPLAY_BATCH_TIMEOUT_MS);
      if (attempt) setAutoplayNote("");
      return next;
    } catch (error) {
      if (attempt || !retryableAutoplayFetch(error)) throw error;
      setAutoplayNote("Connection interrupted · confirming the completed turns…");
    }
  }
}
// Draw one auto-played turn, and do not ask for the next until the browser has
// taken this one. Two states rendered inside a single display refresh are
// composited into one, so a turn drawn without waiting for a frame is a turn
// that was simulated, delivered, drawn — and still never seen. This is the same
// one-turn-per-presented-frame rule the exhibition's own loop keeps.
function autoplayFrame(st) {
  return new Promise(drawn => requestAnimationFrame(() => { render(st); drawn(); }));
}
// Played one turn per request, because a batch is turns nobody watches: the
// engine simulates every turn in it but only the state *after the last one*
// ever comes back, so asking for ten turns draws one frame and silently
// discards nine. That is what "auto-play skips turns" was. Every turn now gets
// its own request and its own animation frame.
//
// Throughput survives the change because the next turn is asked for *before*
// the current one is painted: the engine plays turn N+1 while the browser draws
// turn N, so a turn costs the frame or the engine, never the sum of both. A run
// in a tab that is not being presented pauses rather than racing ahead unseen,
// and resumes by itself — deliberately, and not to be "fixed" with a
// document.hidden guard, which is how this guarantee was lost once already.
async function autoplay(turns) {
  if (SPEC) return;
  if (autoplaying) { autoplayStop = true; return; }
  const button = document.getElementById("autoplaybtn");
  const bar = document.getElementById("autoplaybar");
  const strategy = (document.getElementById("autoplaystrategy") || {}).value || "";
  try { if (strategy) localStorage.setItem(AUTOPLAY_STRATEGY_KEY, strategy); } catch (e) {}
  autoplaying = true; autoplayStop = false;
  if (bar) bar.classList.add("running");
  setAutoplayNote("");
  // Both choices are locked in for the length of the run, so the control says
  // what the agent playing is actually doing.
  for (const field of ["autoplaystrategy", "autoplayturns"])
    document.getElementById(field).disabled = true;
  let left = Math.max(1, turns | 0);
  let inFlight = null;
  try {
    // A turn is in flight from here to the end of the run. The loop paints
    // whatever it asked for before it looks at why it should stop, so a run
    // ended by the Stop button still shows the turn the engine had already
    // played rather than dropping it on the floor.
    inFlight = autoplayBatch(1, strategy);
    while (inFlight) {
      const next = await inFlight;
      if (next.error) throw new Error(next.error);
      const played = +next.autoplayed || 0;
      left -= played;
      // Nothing played means the game ran out: somebody won, or this seat is
      // no longer in it. Otherwise ask for the next turn now, so it is being
      // simulated while this one is on its way to the glass.
      inFlight = played > 0 && left > 0 && !autoplayStop ? autoplayBatch(1, strategy) : null;
      button.textContent = `⏹ Stop · ${left} turn${left === 1 ? "" : "s"} left`;
      sel = null;
      await autoplayFrame(next);
    }
    setAutoplayNote(autoplayStop && left > 0 ? `Stopped · ${left} turns unplayed` : "");
  } catch (e) {
    const errEl = document.getElementById("err");
    errEl.textContent = `auto-play failed: ${e.message || e}`;
    errEl.style.display = "block";
    setTimeout(() => errEl.style.display = "none", 2500);
  } finally {
    // A run that ended on an error can leave the turn it had already asked for
    // with nobody waiting on it. The error above is the one worth reporting;
    // this only keeps the abandoned request from surfacing a second time as an
    // unhandled rejection.
    if (inFlight) inFlight.catch(() => {});
    if (bar) bar.classList.remove("running");
    for (const field of ["autoplaystrategy", "autoplayturns"])
      document.getElementById(field).disabled = false;
    autoplaying = false; autoplayStop = false;
    syncAutoplayLabel();
    drawTurnLoop();
  }
}
document.getElementById("autoplaybtn").onclick = () => autoplay(autoplayRequest());
document.getElementById("autoplayturns").onchange = () => syncAutoplayLabel();
syncAutoplayLabel();
